arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -d '{"query":"{ issues(includeArchived: true, first: 100) { nodes { id identifier title estimate assignee { id name } projectMilestone { id name targetDate } archivedAt } } }"}' 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
if d.get('errors'): print(d['errors']); sys.exit()
want={'435c51de-2007-413e-a207-eb456136ff78','b6f8006a-63d6-4155-a4e2-f81ec078d380'}
n=0
for i in d['data']['issues']['nodes']:
    ms=i.get('projectMilestone') or {}
    if ms.get('id') in want:
        n+=1
        print('MATCH:', i['identifier'], i['title'], '| assignee:', (i.get('assignee') or {}).get('name'), '| est:', i['estimate'])
print('issues in Oct-15 Atlas milestones:', n, '| total issues:', len(d['data']['issues']['nodes']))
"

